def drive(me, enemy, arena):
    m = me.memory
    h = me.heading
    prev = m.get('h', h)
    dh = h - prev
    if dh > 180.0:
        dh = dh - 360.0
    if dh < -180.0:
        dh = dh + 360.0
    m['h'] = h
    y = m.get('y', 0.0)
    y = 0.6 * y + 0.4 * (dh / 0.05)
    m['y'] = y
    r = (me.x * me.x + me.y * me.y) ** 0.5
    if me.airborne or me.on_side or me.inverted:
        return (0.0, 0.0)
    if m.get('mode', 0) == 1:
        if r > 5.0:
            m['mode'] = 0
        else:
            return (-0.7, -0.7)
    e = bearing_to(enemy.x, enemy.y)
    d = distance_to(enemy.x, enemy.y)
    if r > 5.0:
        e = bearing_to(0.0, 0.0)
    des = 2.0 * e
    if des > 200.0:
        des = 200.0
    if des < -200.0:
        des = -200.0
    corr = des - y
    base = 1.0
    if d < 1.2:
        base = 0.85
    if d < 0.7:
        base = 0.6
    if e > 110.0 or e < -110.0:
        base = 0.7
    l = base + 0.02 * corr
    rr = base - 0.02 * corr
    if l > 1.0:
        l = 1.0
    if l < -1.0:
        l = -1.0
    if rr > 1.0:
        rr = 1.0
    if rr < -1.0:
        rr = -1.0
    return (l, rr)


def weapons(me, enemy, arena):
    m = me.memory
    cmds = []
    w = me.weapons.get('front')
    if w is not None and w.get('type') == 'spinner':
        if not me.on_side:
            cmds.append(spin('front', 1800))
    lw = me.weapons.get('back')
    if lw is not None and lw.get('type') == 'lifter':
        t = m.get('lt', 0.0) + 0.05
        m['lt'] = t
        e = bearing_to(enemy.x, enemy.y)
        d = distance_to(enemy.x, enemy.y)
        behind = e > 110.0 or e < -110.0
        stopped = abs(enemy.speed) < 0.3 and not enemy.airborne and enemy.z < 0.06
        if m.get('lift', 0) == 0:
            if behind and stopped and d < 1.8:
                cmds.append(lift('back'))
                m['lift'] = 1
                m['mode'] = 1
                m['lt'] = 0.0
        else:
            if (not behind) or (not stopped) or t > 3.5 or d < 0.55:
                cmds.append(lower('back'))
                m['lift'] = 0
                m['mode'] = 0
                m['lt'] = 0.0
    if me.inverted and me.invertible and (not me.righting) and (not me.airborne):
        if me.battery_wh > 1.0 and me.battery_health > 0.05:
            cmds.append(self_right())
    return cmds

