def drive(me, enemy, arena):
    if me.righting:
        return (0.0, 0.0)
    rr = (me.x * me.x + me.y * me.y) ** 0.5
    if rr > 5.0:
        b = bearing_to(-0.4 * me.x, -0.4 * me.y)
    else:
        b = bearing_to(enemy.x, enemy.y)
    t = b / 25.0
    if t > 1.0:
        t = 1.0
    elif t < -1.0:
        t = -1.0
    f = 1.0 - 0.4 * abs(t)
    return (f - t, f + t)


