def drive(me, enemy, arena):
    try:
        if not me.can_drive:
            return (0.0, 0.0)
        if enemy.inverted or enemy.on_side:
            return (0.0, 0.0)
    except Exception:
        pass
    e = bearing_to(enemy.x, enemy.y)
    d = distance_to(enemy.x, enemy.y)
    r = (me.x * me.x + me.y * me.y) ** 0.5
    if r > 5.0:
        e = bearing_to(0.0, 0.0)
        d = 6.0
    if e > 100.0:
        return (0.9, -0.9)
    if e < -100.0:
        return (-0.9, 0.9)
    base = 0.9
    if d < 1.3:
        base = 0.45
    if d < 0.9:
        base = 0.2
    l = base + 0.015 * e
    rr = base - 0.015 * e
    if l > 1.0:
        l = 1.0
    if l < -1.0:
        l = -1.0
    if rr > 1.0:
        rr = 1.0
    if rr < -1.0:
        rr = -1.0
    return (l, rr)


def weapons(me, enemy, arena):
    cmds = []
    try:
        f = me.weapons.get('front')
        if f is None or f.get('type') != 'flipper':
            return cmds
        shots = f.get('shots_left', 0)
        ready = f.get('ready', False)
        if me.inverted and me.invertible and not me.righting and not me.airborne:
            if shots > 0 and ready:
                cmds.append(self_right())
            return cmds
        if me.on_side or me.airborne:
            return cmds
        if enemy.inverted or enemy.on_side:
            return cmds
        if not ready or shots <= 0:
            return cmds
        e = bearing_to(enemy.x, enemy.y)
        d = distance_to(enemy.x, enemy.y)
        if d < 1.15 and abs(e) < 40.0 and enemy.z < 0.09 and not enemy.airborne:
            cmds.append(flip('front'))
    except Exception:
        pass
    return cmds
